<#
  launch_seeder.ps1 - launch the seeder DETACHED, deterministically (Flow 1h).

  Starts run_seeder.ps1 in its own background process and returns immediately, so
  the seeding run survives the end of the GitHub Copilot tool call:
    Windows       Start-Process -WindowStyle Hidden (the upstream DemoIQ launch path)
    macOS/Linux   a new session via scripts/detach.js (setsid), output to
                  <run folder>/logs/launcher.log
  The administrator's sign-in (admin_signin.ps1) reaches the child through the
  encrypted session store - never through a command line - and that run consumes it.

  Before launching it fails fast, with the next action, when the seeder lacks the
  delegated patch marker, nobody signed in, or the sign-in does not match the config's
  administrator and app (the detached child would otherwise die where nobody sees it).

  The quoting of paths with spaces lives here, once (it was a recurring failure when
  re-typed per run).

  IMPORTANT for the agent: run THIS script as a normal SYNC terminal call
  (pwsh -NoProfile -ExecutionPolicy Bypass -File ...). It returns in seconds.

  Params:
    -SeederScript  path to the regenerated DemoIQ.ps1 (required)
    -ConfigFile    path to the plain DemoIQ_config.json (forwarded verbatim)
    -RunMode       '1' Fast (default) | '2' Full
    -RetryOnFail   auto-answer the end-of-run RETRY menu with one retry
    -Cleanup       a CLEANUP run instead of a seed: the seeder prepares the tenant, deletes
                   the seeded content with delegated tokens and restores the tenant
    -Scope         (cleanup) LastRun (default) | AllRuns
    -ManifestPath  (cleanup) a specific cleanup.config (default: the administrator's
                   OneDrive copy, else every seed run folder)
    -ArchiveLocalDeliverables  (cleanup) zip the targeted runs' local deliverables into
                   <ws>/archive first, then remove them

  Only one DemoIQ run (seed or cleanup) may run at a time: both relax and restore the
  same Conditional Access and MFA settings.

  Output: ONE compact JSON line:
    { ok, kind, launchedAt, processId, runFolder, monitorCommand }
  Pass launchedAt to monitor_seeding.ps1 -SinceTime so the monitor anchors to
  THIS launch and never mistakes a stale prior run for it.
#>
param(
  [Parameter(Mandatory = $true)][string]$SeederScript,
  [string]$ConfigFile,
  [string]$RunMode = '1',
  [switch]$RetryOnFail,
  [switch]$Cleanup,
  [ValidateSet('LastRun', 'AllRuns')][string]$Scope = 'LastRun',
  [string]$ManifestPath,
  [switch]$ArchiveLocalDeliverables
)

$ErrorActionPreference = 'Stop'
. (Join-Path $PSScriptRoot 'session_store.ps1')
function Out-Json($o) { $o | ConvertTo-Json -Compress -Depth 4 }
function Fail-Launch([string]$message) {
  Out-Json @{ ok = $false; error = $message }
  exit 2
}

if ($RunMode -ne '1' -and $RunMode -ne '2') { $RunMode = '1' }
if (-not (Test-Path -LiteralPath $SeederScript)) { Fail-Launch "Seeder script not found: $SeederScript" }
if ($ConfigFile -and -not (Test-Path -LiteralPath $ConfigFile)) { Fail-Launch "Config file not found: $ConfigFile" }
if ($ManifestPath -and -not (Test-Path -LiteralPath $ManifestPath -PathType Leaf)) { Fail-Launch "Manifest not found: $ManifestPath" }
$SeederScript = (Resolve-Path -LiteralPath $SeederScript).Path
if ($ConfigFile) { $ConfigFile = (Resolve-Path -LiteralPath $ConfigFile).Path }
if ($ManifestPath) { $ManifestPath = (Resolve-Path -LiteralPath $ManifestPath).Path }

# Only seeders from this skill's generate.js run (run_seeder.ps1 enforces the same marker).
$head = (Get-Content -LiteralPath $SeederScript -TotalCount 3 -ErrorAction SilentlyContinue) -join "`n"
if ($head -notmatch 'demoiq-seed: delegated patch v2') {
  Fail-Launch 'This seeder was not generated by the current demoiq-seed generate.js. Regenerate it with scripts/generate.js.'
}

# One run at a time: a seed and a cleanup (or two of either) would fight over the same
# Conditional Access exclusions and MFA restore.
$running = @(Get-DemoIQPwshProcess | Where-Object { $_.ProcessId -ne $PID -and $_.CommandLine -match 'run_seeder\.ps1' })
if ($running.Count) {
  Fail-Launch "A DemoIQ run is already in progress (pwsh process $($running[0].ProcessId)). Wait for it to finish (monitor_seeding.ps1) before starting another seed or cleanup."
}

# The run needs the administrator's sign-in. Fail fast here (with the next action) rather
# than letting the detached child die invisibly with 'no-admin-session'.
if (-not (Test-DemoIQSessionSecret -Name 'admin-session')) {
  Fail-Launch 'No administrator sign-in for this run. Run scripts/admin_signin.ps1 (each seed or cleanup run needs its own sign-in).'
}
$signIn = $null
try { $signIn = Read-DemoIQSessionSecret -Name 'admin-session' | ConvertFrom-Json } catch {}
if (-not $signIn) {
  Clear-DemoIQSessionSecret -Name 'admin-session'
  Fail-Launch 'The stored administrator sign-in cannot be read. Run scripts/admin_signin.ps1 again.'
}
$configPath = if ($ConfigFile) { $ConfigFile } else { Join-Path (Split-Path -Parent $SeederScript) 'DemoIQ_config.json' }
if (Test-Path -LiteralPath $configPath) {
  $cfg = $null
  try { $cfg = Get-Content -LiteralPath $configPath -Raw | ConvertFrom-Json } catch {}
  if (-not $cfg -or $cfg.v -eq 'cdx-enc-v1') { Fail-Launch "The config is not a plain DemoIQ config: $configPath. Convert or re-save it with the skill." }
  # A sign-in that cannot serve this config is cleared: it would otherwise sit on disk unused.
  if ([string]$cfg.adminUpn -ne [string]$signIn.upn) {
    Clear-DemoIQSessionSecret -Name 'admin-session'
    Fail-Launch "The administrator signed in as $($signIn.upn), but the config's administrator is $($cfg.adminUpn). Run scripts/admin_signin.ps1 -ExpectedUpn $($cfg.adminUpn)."
  }
  if ([string]$cfg.existingAppId -ne [string]$signIn.clientId) {
    Clear-DemoIQSessionSecret -Name 'admin-session'
    Fail-Launch "The config uses app $($cfg.existingAppId), but this deployment's DemoIQ app is $($signIn.clientId). Regenerate the config from the deployment receipts."
  }
}
$signIn = $null

$runSeeder = Join-Path $PSScriptRoot 'run_seeder.ps1'
$launchedAt = (Get-Date).ToString('s')   # anchor for monitor_seeding.ps1 -SinceTime
$outputFolder = Split-Path -Parent $SeederScript

$seederArgs = @(
  '-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', $runSeeder,
  '-SeederScript', $SeederScript,
  '-RunMode', $RunMode
)
if ($ConfigFile) { $seederArgs += @('-ConfigFile', $ConfigFile) }
if ($RetryOnFail -and -not $Cleanup) { $seederArgs += '-RetryOnFail' }
if ($Cleanup) {
  $seederArgs += @('-Cleanup', '-CleanupScope', $Scope)
  if ($ManifestPath) { $seederArgs += @('-CleanupManifest', $ManifestPath) }
  if ($ArchiveLocalDeliverables) { $seederArgs += '-ArchiveLocalDeliverables' }
}

$pwshExe = if ($env:DEMOIQ_PWSH_PATH) { $env:DEMOIQ_PWSH_PATH } else { (Get-Command pwsh -ErrorAction SilentlyContinue).Source }
if (-not $pwshExe) { Fail-Launch 'PowerShell 7 (pwsh) was not found on PATH.' }
try {
  if (Test-DemoIQWindows) {
    # Join into a SINGLE quoted string so paths with SPACES survive: an ARRAY passed to
    # Start-Process is NOT quoted, so a spaced path splits into multiple arguments.
    $argString = ($seederArgs | ForEach-Object { if ($_ -match '\s') { '"' + $_ + '"' } else { $_ } }) -join ' '
    $proc = Start-Process -FilePath $pwshExe -ArgumentList $argString -WindowStyle Hidden -PassThru -ErrorAction Stop
    $childPid = $proc.Id
  } else {
    $logDir = Join-Path $outputFolder 'logs'
    New-Item -ItemType Directory -Force -Path $logDir | Out-Null
    $childPid = Start-DemoIQDetachedProcess -FilePath $pwshExe -ArgumentList $seederArgs `
      -LogFile (Join-Path $logDir 'launcher.log') -WorkingDirectory $outputFolder
  }
} catch {
  Fail-Launch ("Failed to start the seeder process: " + ($_.Exception.Message -replace '\s+', ' '))
}

# Record the launch in the run's manifest (run.json beside the seeder, written by
# new_run.ps1). Merge - never clobber the creation fields. If no manifest exists
# (legacy flat layout), create a minimal one so run_history still gets the metadata.
$runJsonPath = Join-Path $outputFolder 'run.json'
try {
  $manifest = if (Test-Path -LiteralPath $runJsonPath) { Get-Content -LiteralPath $runJsonPath -Raw | ConvertFrom-Json } else { [pscustomobject]@{} }
  foreach ($kv in @(
    @{ k = 'launchedAt';  v = $launchedAt },
    @{ k = 'kind';        v = $(if ($Cleanup) { 'cleanup' } else { 'seed' }) },
    @{ k = 'runMode';     v = $(if ($Cleanup) { $null } else { $RunMode }) },
    @{ k = 'cleanupScope'; v = $(if ($Cleanup) { $Scope } else { $null }) },
    @{ k = 'processId';   v = $childPid },
    @{ k = 'seederScript'; v = $SeederScript },
    @{ k = 'status';      v = 'launched' }
  )) { $manifest | Add-Member -NotePropertyName $kv.k -NotePropertyValue $kv.v -Force }
  if ($ConfigFile) { $manifest | Add-Member -NotePropertyName 'configFile' -NotePropertyValue $ConfigFile -Force }
  # Merge the app identity stamped by generate.js (run_identity.json beside the seeder)
  # so run.json alone answers "which app and Speech resource did this run use".
  $idPath = Join-Path $outputFolder 'run_identity.json'
  if (Test-Path -LiteralPath $idPath) {
    try {
      $rid = Get-Content -LiteralPath $idPath -Raw | ConvertFrom-Json
      foreach ($k in 'appId', 'speechResourceId', 'adminUpn') {
        if ($rid.$k) { $manifest | Add-Member -NotePropertyName $k -NotePropertyValue $rid.$k -Force }
      }
    } catch {}
  }
  ($manifest | ConvertTo-Json -Depth 4) | Set-Content -LiteralPath $runJsonPath -Encoding UTF8
} catch {} # manifest is best-effort metadata; a write failure must never block the launch

$monitor = Join-Path $PSScriptRoot 'monitor_seeding.ps1'
Out-Json ([ordered]@{
  ok = $true
  kind = $(if ($Cleanup) { 'cleanup' } else { 'seed' })
  launchedAt = $launchedAt
  processId = $childPid
  runFolder = $outputFolder
  monitorCommand = "pwsh -NoProfile -ExecutionPolicy Bypass -File `"$monitor`" -OutputFolder `"$outputFolder`" -SinceTime `"$launchedAt`" -WaitSeconds 60"
})
